'use strict';
// Deliberately standalone: no Supabase, remote API, production data or service worker.
const KEY='cruza-evolution-preview-v1';
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
const decorate=html=>html.replaceAll('↗','<svg class="inline-arrow" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 13 13 3M4 3h9v9"/></svg>').replaceAll('↳','<svg class="inline-arrow turn" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 3v9h12m-5-5 5 5-5 5"/></svg>');
const defaults=()=>({team:'U17 · Football à 11',match:'next',savedAt:null,offline:false,role:'responsable',profile:{name:'Enzo Mouchet',email:'educateur@exemple.fr',photo:''},clubs:[],photos:[],drafts:{},reports:{},attendance:{},session:[],ready:{},played:{}});
let state=defaults(),storageFailed=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))state={...defaults(),...parsed};}}catch{storageFailed=true;}
const matches={next:{id:'next',opponent:'MÉRAL COSSÉ US',short:'Méral Cossé',date:'Dimanche 22 novembre',time:'15 h 00',place:'Stade du club · domicile',number:'J8',initials:'MC'},past:{id:'past',opponent:'LAVAL BOURNY',short:'Laval Bourny',date:'Dimanche 15 novembre',time:'15 h 00',place:'À l’extérieur',number:'J7',initials:'LB'},after:{id:'after',opponent:'AS ANDOUILLÉ',short:'AS Andouillé',date:'Dimanche 29 novembre',time:'15 h 00',place:'À l’extérieur',number:'J9',initials:'ASA'}};
if(!matches[state.match])state.match='next';
let currentRoute='',currentTab='causerie',exerciseFilter='Tous',exerciseSearch='',attendanceDay='18',wizardStep=1,wizardData={name:'',city:'',color:'#2855a7',teams:'U15, U17',email:''};
const players=['Louis Martin','Gabriel Moreau','Arthur Bernard','Lucas Petit','Hugo Robert','Jules Richard','Raphaël Durand','Adam Dubois','Noah Laurent','Ethan Michel','Nathan Lefèvre','Paul Simon','Sacha Leroy','Tom Roux','Maël Fontaine','Léo Garnier'];
const icons={accueil:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',match:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M12 4v16"/><circle cx="12" cy="12" r="3"/>',seances:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v4H9zM9 12h6M9 16h6"/>',agenda:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M7 14h2M14 14h2M7 17h2"/>',bilans:'<path d="M4 20h16M6 16v-5M12 16V4M18 16V8"/>',effectif:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v2"/>',responsable:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',club:'<path d="M3 21V8l9-5 9 5v13M8 21v-6h8v6M8 9h1M15 9h1M8 12h1M15 12h1M1 21h22"/>',reglages:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3Z"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.match}</svg>`;
const navItems=[['accueil','Accueil'],['match','Match & causerie'],['seances','Séances'],['agenda','Agenda'],['bilans','Bilans'],['effectif','Votre effectif'],['responsable','Responsable'],['club','Mon club'],['reglages','Mon compte']];
const btn=(label,action,kind='primary',extra='')=>`<button class="button ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,route,kind='primary')=>`<a class="button ${kind}" href="#${route}">${label}</a>`;
const pill=(text,color='')=>`<span class="pill ${color}">${text}</span>`;
const m=()=>matches[state.match];
const timeLabel=()=>state.savedAt?new Date(state.savedAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):'pas encore enregistré';
function persist(silent=false){state.savedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;if(!silent)toast('Enregistré sur cet appareil — aperçu uniquement.');}catch{storageFailed=true;toast('Stockage indisponible. Gardez la page ouverte et téléchargez votre copie.');}updateHeader();return !storageFailed;}
let toastTimer;function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),4300);}
function updateHeader(){const label=document.querySelector('#save-indicator span');label.textContent=storageFailed?'Copie à exporter':state.offline?'Mode hors ligne':'Sur cet appareil';document.querySelector('#save-indicator i').style.background=storageFailed?'#d94a47':state.offline?'#b58d35':'#21835f';document.querySelector('#team-select').value=state.team;document.querySelector('#profile-button>span:last-child').textContent=state.profile.name;}
function heading(eyebrow,title,desc='',action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function context(){return `<div class="match-context"><div><div class="context-label">MÊME MATCH · AGENDA / CAUSERIE / BILAN</div><strong>Stade Mayennais — ${E(m().short)}</strong><small>${m().date} · ${m().time} · ${E(state.team.split(' · ')[0])} · ${m().number}</small></div>${btn('Changer de match','choose-match','ghost small')}</div>`;}
function matchSummary(){return `<div class="match-summary"><div class="match-team"><img class="team-crest" src="../assets/club-logo.jpg" alt=""><div>Stade Mayennais<small>${E(state.team.split(' · ')[0])} · ${state.match==='next'?'Domicile':'Extérieur'}</small></div></div><div class="match-date">${m().date.replace('Dimanche ','Dim. ')}<strong>${state.match==='past'?'2 — 1':state.played[state.match]?'Match joué':'15:00'}</strong>${m().number} · Championnat fictif</div><div class="match-team"><div>${E(m().short)}<small>Adversaire</small></div><span class="opponent-crest">${m().initials}</span></div></div>`;}
function flow(){const played=state.match==='past'||state.played[state.match],ready=state.ready[state.match],reported=state.reports[state.match]?.saved;return `<div class="flow"><div class="flow-step done">✓ Match renseigné<span>Depuis l’agenda</span></div><div class="flow-step ${ready||played?'done':'current'}">${ready?'✓ ':''}Causerie<span>${ready?'Prête à présenter':'À préparer'}</span></div><div class="flow-step ${played?'done':''}">Match joué<span>${played?'Résultat disponible':'Dimanche · 15 h'}</span></div><div class="flow-step ${reported?'done':played?'current':''}">Bilan<span>${reported?'Enregistré ici':played?'À compléter':'Après le match'}</span></div></div>`;}
function home(){const hasDraft=!!state.drafts[state.match],played=state.match==='past'||state.played[state.match],reported=state.reports[state.match]?.saved;return `${heading('Le vestiaire · Mardi 17 novembre 2026','Chaque semaine, un cap commun.','Votre équipe, vos préparations et la suite à donner — au même endroit.')}
<section class="hero"><div class="hero-top"><div class="eyebrow">STADE MAYENNAIS · ${E(state.team.split(' · ')[0])}</div><span class="hero-badge">DU BUREAU AU TERRAIN</span></div><img class="hero-emblem" src="../assets/club-logo.jpg" alt=""><div><h2>Bonjour ${E(state.profile.name.split(' ')[0])}.<br>${reported?'Le bilan est fait.<br>Préparons la suite.':played?'Le match est terminé.<br>Place au bilan.':'Le prochain match<br>se prépare ici.'}</h2><p>${played?'Retrouvez vos intentions contre '+E(m().short)+' et donnez une suite au travail du groupe.':E(m().short)+' est déjà renseigné dans votre agenda. Retrouvez votre causerie, sans repartir de zéro.'}</p></div><div class="hero-foot"><div class="actions">${link(reported?'Préparer la prochaine séance ↗':played?'Compléter le bilan ↗':hasDraft?'Reprendre ma causerie ↗':'Préparer ma causerie ↗',reported?'seances':played?'bilans':'match','light')}${link('Voir ma semaine','agenda','ghost')}</div><div class="hero-step"><span></span> ${reported?'Bilan enregistré':played?'Bilan à compléter':state.ready[state.match]?'Causerie prête':'Préparation en cours'} · ${m().number}</div></div></section>
<div class="dashboard-grid"><section class="card"><div class="card-header"><div><h2>Votre fil du match</h2><p>Un seul match, de la préparation au bilan.</p></div>${pill('Relié à l’agenda','green')}</div>${matchSummary()}${flow()}<div class="actions">${link('Ouvrir la préparation','match')}${link('Ouvrir le bilan','bilans','ghost')}</div><div class="card-note">Match de démonstration. L’adversaire et la date vous suivent dans chaque écran.</div></section><section class="card"><div class="card-header"><div><h2>Cette semaine</h2><p>16 — 22 novembre · calendrier fictif</p></div><a class="text-link" href="#agenda">Tout voir ↗</a></div><a href="#seances" class="event"><div class="date-square">MER<strong>18</strong></div><div class="event-content"><strong>Sortir du pressing</strong><small>Entraînement · 16 h · 75 min</small></div><span class="event-arrow">↗</span></a><a href="#effectif" class="event"><div class="date-square">VEN<strong>20</strong></div><div class="event-content"><strong>Derniers réglages</strong><small>Entraînement · 18 h · présences à saisir</small></div><span class="event-arrow">↗</span></a><a href="#match" class="event"><div class="date-square">DIM<strong>22</strong></div><div class="event-content"><strong>Stade Mayennais — Méral Cossé</strong><small>Championnat · 15 h · à domicile</small></div><span class="event-arrow">↗</span></a></section></div>
<div class="stats-grid"><section class="card"><div class="metric-label">Présence aux entraînements</div><div class="metric-value">88 <small>%</small></div><div class="metric-detail">42 présences / 48 attendues · 3 séances</div><div class="mini-bars" aria-hidden="true">${[54,73,65,80,76,88].map(n=>`<i style="height:${n/3}%"></i>`).join('')}</div></section><section class="card"><div class="metric-label">Forme · 5 derniers matchs</div><div class="metric-value">10 <small>pts / 15</small></div><div class="metric-detail">Championnat · résultats fictifs</div><div class="results"><span class="result">V</span><span class="result draw">N</span><span class="result loss">D</span><span class="result">V</span><span class="result">V</span></div></section><section class="card"><div class="metric-label">Préparation de la semaine</div><div class="metric-value">${state.ready[state.match]?'3':'2'} <small>/ 3</small></div><div class="metric-detail">Agenda · séance · causerie</div><div class="progress" aria-label="Préparation ${state.ready[state.match]?'100':'67'} pour cent"><i style="width:${state.ready[state.match]?'100':'67'}%"></i></div></section></div>
<section class="bottom-insight"><span class="insight-icon">↳</span><div><strong>Du dernier bilan à la prochaine séance.</strong><p>Point identifié contre Laval Bourny : trouver un appui à l’intérieur sous pression.</p></div><a href="#seances" class="text-link">Travailler ce point ↗</a></section>`;}
function pitch(){const pos=[[50,90],[15,70],[38,73],[62,73],[85,70],[25,48],[50,52],[75,48],[20,23],[50,16],[80,23]];return `<div class="pitch" aria-label="Composition de démonstration en 4-3-3"><div class="pitch-circle"></div>${pos.map(([x,y],i)=>`<span class="player-pin" style="left:${x}%;top:${y}%"><b>${i+1}</b><small>${players[i].split(' ')[0]}</small></span>`).join('')}</div>`;}
function matchPage(){const draft=state.drafts[state.match]||{},ready=state.ready[state.match];return `${heading('Préparer · Jouer · Débriefer','Votre match, de A à Z.','Les informations de l’agenda sont déjà reprises ici.',btn('Voir le suivi','sync','ghost'))}${context()}${flow()}<div class="tabs" role="tablist" aria-label="Préparation du match">${[['causerie','Causerie'],['composition','Composition'],['animation','Animations & intentions']].map(([id,title])=>`<button class="tab ${currentTab===id?'active':''}" role="tab" aria-selected="${currentTab===id}" data-action="tab" data-tab="${id}">${title}</button>`).join('')}</div>
${currentTab==='causerie'?`<div class="two-col"><form id="talk-form" class="card"><div class="card-header"><h2><span class="section-number">01</span>Le message du vestiaire</h2>${pill(ready?'Prête':'En préparation',ready?'green':'gold')}</div><label class="field">Contexte du match<textarea name="context" placeholder="L’enjeu, l’adversaire, ce que le groupe doit savoir…">${E(draft.context??'À domicile, imposer notre rythme dès les premières minutes. Méral Cossé cherche à jouer vite vers l’avant : restons proches les uns des autres.')}</textarea><small>Un espace dédié, conservé avec la causerie.</small></label><label class="field">Notre intention de jeu<textarea name="intention">${E(draft.intention??'Attirer sur un côté pour renverser. Trouver le joueur libre à l’intérieur avant de chercher la profondeur.')}</textarea></label><label class="field">Les trois messages clés<textarea name="messages">${E(draft.messages??'1. Être disponibles autour du porteur.\n2. Réagir ensemble à la perte.\n3. Jouer avec confiance et solidarité.')}</textarea></label><div class="save-footer"><button type="submit" class="button primary">Enregistrer ma préparation</button><small>${state.drafts[state.match]?'Enregistrée ici · '+timeLabel():'Brouillon de démonstration'}</small></div></form><div class="stack"><section class="card"><div class="card-header"><h2><span class="section-number">02</span>Avant le coup d’envoi</h2></div><div class="check-list"><label><input type="checkbox" checked disabled> Adversaire et date renseignés</label><label><input type="checkbox" ${draft.checked?'checked':''} data-action="check-prep"> Messages du groupe relus</label><label><input type="checkbox" ${ready?'checked':''} data-action="ready"> Causerie prête à présenter</label></div><div class="card-note">La composition, les intentions et le contexte restent associés à ${E(m().short)}.</div></section><section class="card"><div class="card-header"><h2>Du bureau au terrain</h2></div>${pitch()}<div class="actions" style="margin-top:16px">${btn('Voir les diapositives','slides','ghost')}</div></section><div class="notice blue">Pour explorer la suite du parcours : simulez la fin du match. Le bilan reprendra le bon adversaire et les intentions préparées.</div>${btn('Tester le parcours après-match →','after-match','dark')}</div></div>`:currentTab==='composition'?`<div class="two-col"><section class="card"><div class="card-header"><h2>Notre organisation · 4-3-3</h2>${pill('Même document')}</div>${pitch()}<p class="tactical-note">Les joueurs sont fictifs. Cette vue illustre la composition attachée au match sélectionné.</p></section><section class="card"><div class="card-header"><h2>Le groupe convoqué</h2>${pill('16 joueurs')}</div>${players.slice(0,8).map((name,i)=>`<div class="list-row"><span class="list-number">${i+1}</span><div class="grow"><strong>${name}</strong><small>${i===0?'Gardien':i<5?'Défenseur':'Milieu'} · joueur fictif</small></div>${pill('Disponible','green')}</div>`).join('')}<p class="card-note">+ 8 joueurs dans l’effectif de démonstration.</p></section></div>`:`<div class="two-col"><form id="animation-form" class="card"><div class="card-header"><h2>Ce que l’on veut mettre en place</h2></div><label class="field">Avec le ballon<textarea name="withBall">${E(draft.withBall??'Créer une supériorité autour du porteur. Fixer à gauche, trouver le troisième homme, renverser à droite.')}</textarea></label><label class="field">Sans le ballon<textarea name="withoutBall">${E(draft.withoutBall??'Bloc compact. Fermer l’axe et orienter vers la ligne. Déclencher ensemble sur une passe latérale.')}</textarea></label><label class="field">À la transition<textarea name="transition">${E(draft.transition??'À la perte : cinq secondes pour récupérer ensemble. À la récupération : sécuriser la première passe.')}</textarea></label><button class="button primary" type="submit">Enregistrer les intentions</button></form><section class="card"><div class="card-header"><h2>Une intention, une situation</h2></div>${exercisePreview(1)}<h3>Sortir de la pression à trois</h3><p class="report-note">Cette situation prépare le troisième homme que vous souhaitez retrouver dimanche.</p>${link('Retrouver dans les séances','seances','ghost')}<p class="card-note">Les textes saisis ici apparaissent aussi dans l’aperçu des diapositives.</p></section></div>`}`;}
const exercises=[{title:'Sortir du pressing',theme:'Possession',detail:'4 contre 4 + 2 jokers · 20 min',source:'Point du dernier bilan'},{title:'Réagir à la perte',theme:'Transition',detail:'5 contre 5 · 15 min',source:'Intention de la causerie'},{title:'Attaquer la profondeur',theme:'Finition',detail:'3 contre 2 · 20 min',source:'Développer la finition'},{title:'Trouver le troisième homme',theme:'Possession',detail:'6 contre 3 · 15 min',source:'Préparer le prochain match'},{title:'Presser ensemble',theme:'Transition',detail:'7 contre 7 · 25 min',source:'Défendre en avançant'},{title:'Finir après un renversement',theme:'Finition',detail:'4 contre 3 · 20 min',source:'Créer un décalage'}];
function exercisePreview(index){return `<div class="exercise-preview" aria-hidden="true">${[[18,30],[35,64],[49,23],[64,58],[79,28],[83,72]].map(([x,y],i)=>`<span style="left:${x+(index%2?2:0)}%;top:${y}%">${i%2?'×':'○'}</span>`).join('')}</div>`;}
function sessionsPage(){const followUp=state.reports[state.match]?.nextSession;const filtered=exercises.map((e,i)=>({...e,index:i})).filter(e=>(exerciseFilter==='Tous'||e.theme===exerciseFilter)&&e.title.toLowerCase().includes(exerciseSearch.toLowerCase()));return `${heading('Le terrain · Une séance qui a du sens','Préparer la prochaine séance.','Mercredi 18 novembre · 16 h · 75 min · 16 joueurs fictifs',btn('Ma séance · '+state.session.length+' situation(s)','session','dark'))}<section class="bottom-insight" style="margin:0 0 24px"><span class="insight-icon">↳</span><div><strong>Le fil conducteur : jouer sous pression.</strong><p>${followUp?E(followUp):'Issu du bilan contre Laval Bourny · à réinvestir contre '+E(m().short)+'.'}</p></div><a href="#bilans" class="text-link">Revoir le bilan ↗</a></section><div class="page-heading"><div class="filters" style="margin:0">${['Tous','Possession','Transition','Finition'].map(t=>`<button class="filter-button ${exerciseFilter===t?'active':''}" data-action="filter" data-filter="${t}">${t}</button>`).join('')}</div><input id="exercise-search" class="search-input" placeholder="Rechercher une situation…" aria-label="Rechercher une situation" value="${E(exerciseSearch)}"></div><div class="exercise-grid">${filtered.length?filtered.map(ex=>`<article class="card exercise-card">${exercisePreview(ex.index)}<div class="exercise-copy">${pill(ex.theme)}<h3 style="margin-top:10px">${ex.title}</h3><p>${ex.detail}</p><div class="actions">${btn(state.session.includes(ex.index)?'✓ Ajoutée':'Ajouter à ma séance','add-exercise',state.session.includes(ex.index)?'ghost small':'primary small',`data-index="${ex.index}"`)}${btn('Détails','exercise-detail','ghost small',`data-index="${ex.index}"`)}</div><div class="card-note">${ex.source}</div></div></article>`).join(''):'<div class="notice">Aucune situation de démonstration ne correspond à votre recherche.</div>'}</div><p class="card-note">Aperçu de 6 situations fictives. La bibliothèque réelle du site est conservée et n’est pas chargée dans cette maquette.</p>`;}
function agendaPage(){return `${heading('Les rendez-vous du groupe','Une semaine lisible.','Tout reste accessible depuis son onglet ; l’agenda fait le lien.',btn('Ajouter un rendez-vous','add-event','ghost'))}<div class="card-header"><div class="actions"><h2>16 — 22 novembre 2026</h2>${pill('Semaine de démonstration')}</div>${link('Pointer les présences','effectif','ghost small')}</div><div class="calendar-scroll"><div class="week-grid">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map((day,i)=>`<div class="day ${i===1?'today':''}"><div class="day-head">${day}<strong>${16+i}</strong></div>${i===2?'<a href="#seances" class="agenda-event"><small>16:00 — 17:15</small><strong>Sortir du pressing</strong>Entraînement<br><small>→ Préparer la séance</small></a>':i===4?'<a href="#effectif" class="agenda-event"><small>18:00 — 19:15</small><strong>Derniers réglages</strong>Entraînement<br><small>→ Saisir les présences</small></a>':i===6?'<button class="agenda-event match" data-action="select-match" data-match="next"><small>15:00 · Championnat</small><strong>Méral Cossé US</strong>À domicile<br><small>→ Ouvrir la causerie</small></button>':''}</div>`).join('')}</div></div><div class="two-col" style="margin-top:22px"><section class="card"><div class="card-header"><h2>Les matchs du groupe</h2></div>${Object.values(matches).map(match=>`<div class="list-row"><span class="list-number">${match.number}</span><div class="grow"><strong>${E(match.short)}</strong><small>${match.date} · ${match.time}</small></div>${btn(state.match===match.id?'Match actif':'Ouvrir','select-match',state.match===match.id?'primary small':'ghost small',`data-match="${match.id}"`)}</div>`).join('')}</section><section class="card"><div class="card-header"><h2>Plus besoin de tout ressaisir.</h2></div><p class="report-note">Ouvrez un match : son adversaire, sa date et son équipe sont repris dans la préparation. Retrouvez ensuite le même contexte dans le bilan.</p><div class="notice blue">Chaque rencontre possède son propre brouillon dans cet aperçu. Vous pouvez changer de match sans mélanger les textes.</div></section></div>`;}
function reportsPage(){const previous=state.match==='past',report=state.reports[state.match]||{},draft=state.drafts[state.match]||{};return `${heading('Observer · Comprendre · Transmettre','Le bilan prolonge la causerie.','Les intentions préparées restent visibles pour évaluer le même match.')}${context()}${!previous&&!state.played[state.match]?`<div class="notice blue" style="margin-bottom:22px">Ce match est à venir. Vous pouvez préparer la trame du bilan, ou ${btn('simuler le match joué','after-match','ghost small')} pour découvrir la suite du parcours.</div>`:''}<div class="two-col"><form id="report-form" class="card"><div class="card-header"><h2><span class="section-number">01</span>Ce que le match nous apprend</h2>${pill(report.saved?'Enregistré ici':'À compléter',report.saved?'green':'gold')}</div><div class="score-row"><label class="field">Nous<input class="score-input" name="homeScore" type="number" min="0" max="99" value="${E(report.homeScore??(previous?'2':''))}"></label><strong>—</strong><label class="field">Adversaire<input class="score-input" name="awayScore" type="number" min="0" max="99" value="${E(report.awayScore??(previous?'1':''))}"></label></div><label class="field">Ce qui a fonctionné<textarea name="positive">${E(report.positive??(previous?'Notre solidarité et les déplacements autour du porteur ont créé des solutions.':''))}</textarea></label><label class="field">Le point à travailler<textarea name="improve">${E(report.improve??(previous?'Trouver un appui intérieur plus tôt quand l’adversaire presse.':''))}</textarea></label><label class="field">À reprendre à l’entraînement<textarea name="nextSession">${E(report.nextSession??'Créer des situations avec un troisième homme pour sortir de la pression.')}</textarea></label><div class="save-footer"><button class="button primary" type="submit">Enregistrer le bilan</button>${link('Préparer la séance suivante','seances','ghost')}</div></form><div class="stack"><section class="card"><div class="card-header"><h2><span class="section-number">02</span>Ce que l’on avait préparé</h2></div><div class="eyebrow">INTENTION DE JEU</div><p class="report-note">${E(draft.intention??'Attirer sur un côté pour renverser. Trouver le joueur libre à l’intérieur avant de chercher la profondeur.')}</p><div class="eyebrow" style="margin-top:20px">MESSAGES DU VESTIAIRE</div><p class="report-note" style="white-space:pre-line">${E(draft.messages??'Être disponibles autour du porteur.\nRéagir ensemble à la perte.\nJouer avec confiance et solidarité.')}</p>${link('Revoir la causerie','match','ghost small')}</section><section class="card"><div class="card-header"><h2>Le cycle continue</h2></div><div class="list-row"><span class="list-number">1</span><div><strong>Un constat dans le bilan</strong><small>Identifier un point concret.</small></div></div><div class="list-row"><span class="list-number">2</span><div><strong>Une situation à l’entraînement</strong><small>Donner un prolongement sur le terrain.</small></div></div><div class="list-row"><span class="list-number">3</span><div><strong>Une intention au prochain match</strong><small>Voir si le groupe progresse.</small></div></div></section></div></div>`;}
function attendancePage(){const attendance=state.attendance[attendanceDay]||{};const count=Object.values(attendance).filter(s=>s==='present').length;return `${heading('Le groupe · Les présences','Chaque joueur compte.','Les jours de séance sont affichés pour tout l’effectif.',btn('Tous présents','all-present','ghost'))}<div class="date-switcher">${['18','20'].map(day=>`<button class="button small ${attendanceDay===day?'active':''}" data-action="attendance-day" data-day="${day}">${day==='18'?'Mer. 18 novembre · 16 h':'Ven. 20 novembre · 18 h'}</button>`).join('')}<span class="pill green">${count} / 16 présents</span></div><section class="card"><div class="card-header"><div><h2>${attendanceDay==='18'?'Sortir du pressing':'Derniers réglages'}</h2><p>Appuyez sur P, A ou E pour chaque joueur. Le pointage est conservé sur cet appareil.</p></div></div><div class="attendance-legend"><span>P · Présent</span><span>A · Absent</span><span>E · Excusé</span></div><div class="table-wrap"><table class="attendance-table"><thead><tr><th>JOUEUR FICTIF</th><th>POSTE</th><th>MER. 18 NOV.</th><th>VEN. 20 NOV.</th></tr></thead><tbody>${players.map((name,i)=>`<tr><td><div class="player-cell"><span class="avatar">${name.split(' ').map(w=>w[0]).join('')}</span><strong>${name}</strong></div></td><td>${i===0?'GB':i<6?'DEF':i<11?'MIL':'ATT'}</td>${['18','20'].map(day=>`<td><div class="attendance-buttons" role="group" aria-label="Présence de ${name} le ${day} novembre">${[['present','P','Présent'],['absent','A','Absent'],['excused','E','Excusé']].map(([status,initial,label])=>`<button class="attendance-button ${(state.attendance[day]||{})[i]===status?'selected':''}" aria-label="${label}" aria-pressed="${(state.attendance[day]||{})[i]===status}" data-action="presence" data-day="${day}" data-player="${i}" data-presence="${status}">${initial}</button>`).join('')}</div></td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function managerPage(){return `${heading('Prendre du recul · Accompagner','Une vision claire du club.','Repérer les besoins de chaque catégorie, puis accompagner l’éducateur.',btn('Exporter la synthèse','export-manager','ghost'))}<div class="role-demo"><span>Tester la vue :</span><select id="role-select" aria-label="Rôle de démonstration"><option value="responsable" ${state.role==='responsable'?'selected':''}>Responsable du club</option><option value="educateur" ${state.role==='educateur'?'selected':''}>Éducateur</option></select>${pill('Simulation des rôles')}</div>${state.role==='educateur'?`<section class="card big-empty">${icon('responsable')}<h2>Un espace réservé au responsable.</h2><p>Dans le produit final, les autorisations doivent aussi être vérifiées par Supabase.<br>Changer ce sélecteur ne donne aucun accès à des données réelles.</p>${link('Revenir à mon équipe','accueil')}</section>`:`<div class="notice blue" style="margin-bottom:20px">Données entièrement fictives. Ce tableau illustre le suivi ; il ne constitue pas un audit de sécurité ou une connexion aux comptes des éducateurs.</div><div class="stats-grid" style="margin-top:0;margin-bottom:22px">${[['Équipes suivies','3','U15 · U17 · Seniors'],['Présence club','86 %','129 présences / 150 attendues'],['Bilans renseignés','8 / 10','Matchs joués · novembre']].map(([label,value,detail])=>`<section class="card"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-detail">${detail}</div></section>`).join('')}</div><div class="two-col"><section class="card"><div class="card-header"><div><h2>Assiduité des catégories</h2><p>6 dernières séances · présences / attendus</p></div>${pill('Novembre')}</div><div class="chart">${[78,85,82,91,84,88].map((n,i)=>`<div class="chart-column"><div class="chart-bar" style="height:${n}%"><strong>${n} %</strong></div><span>S${i+1}</span></div>`).join('')}</div><p class="card-note">Échantillon fictif. Le pourcentage doit s’appuyer sur les joueurs attendus, pas sur un effectif approximatif.</p></section><section class="card"><div class="card-header"><h2>À accompagner cette semaine</h2>${pill('2 points','gold')}</div><div class="list-row"><span class="list-number">!</span><div><strong>U15 · Assiduité en baisse</strong><small>76 % · contre 84 % sur la période précédente</small></div></div><div class="list-row"><span class="list-number">↳</span><div><strong>Seniors · Deux bilans à compléter</strong><small>À échanger avec l’éducateur, sans classement individuel.</small></div></div><div class="notice" style="margin-top:18px">Les chiffres servent à ouvrir une discussion et à soutenir les éducateurs.</div></section></div><div class="exercise-grid" style="margin-top:22px">${[['U15','Éducateur A','76','3 / 4'],['U17','Éducateur B','88','4 / 4'],['Seniors','Éducateur C','94','1 / 2']].map(([cat,name,pres,reports])=>`<section class="card category-card"><div class="card-header"><div><h3>${cat}</h3><p>${name} · profil fictif</p></div>${pill(cat==='U15'?'À accompagner':'À jour',cat==='U15'?'gold':'green')}</div><div class="category-metrics"><div><strong>${pres} %</strong><small>Assiduité</small></div><div><strong>${reports}</strong><small>Bilans</small></div><div><strong>6</strong><small>Séances</small></div></div><div class="progress"><i style="width:${pres}%"></i></div>${btn('Voir le détail de la catégorie','category','ghost small',`data-category="${cat}" style="margin-top:18px"`)}</section>`).join('')}</div>`}`;}
function clubPage(){return `${heading('Une identité · Plusieurs équipes','Le club fait le lien.','Une base commune, adaptée à l’identité de chaque club.',btn('Tester la création d’un club','new-club','primary'))}<div class="two-col"><section class="card"><div class="profile-header"><img src="../assets/club-logo.jpg" alt="Écusson du Stade Mayennais"><div><h2>Stade Mayennais</h2><p class="subtitle">Mayenne · Football · club de démonstration</p></div></div><div class="club-colors"><span class="swatch" style="background:#142c4b"></span><span class="swatch" style="background:#2855a7"></span><span class="swatch" style="background:#e33137"></span><span class="swatch" style="background:#f2ebdc"></span></div><p class="report-note">Une identité conservée : écusson du club, bleu profond, rouge et photos du terrain. Les composants restent cohérents entre l’espace éducateur et l’espace responsable.</p><div class="list-row"><div class="grow"><strong>3 catégories</strong><small>Chaque équipe conserve son agenda et ses préparations.</small></div>${pill('U15 · U17 · Seniors')}</div><div class="list-row"><div class="grow"><strong>Des rôles clairs</strong><small>Éducateur · responsable · administrateur</small></div>${link('Voir la démonstration','responsable','ghost small')}</div></section><section class="card"><div class="card-header"><h2>Un autre club, la même application.</h2>${pill('Parcours pilote')}</div><div class="list-row"><span class="list-number">1</span><div><strong>Identité du club</strong><small>Nom, ville, couleur principale.</small></div></div><div class="list-row"><span class="list-number">2</span><div><strong>Équipes & responsable</strong><small>Préparer les catégories et le contact.</small></div></div><div class="list-row"><span class="list-number">3</span><div><strong>Vérification avant création</strong><small>Valider les informations, puis démarrer.</small></div></div><div class="notice blue" style="margin:20px 0">L’aperçu prépare une configuration locale. Il ne crée ni compte, ni projet Supabase et n’envoie aucune invitation.</div>${btn('Découvrir le parcours →','new-club','dark')}</section></div>${state.clubs.length?`<section class="card" style="margin-top:22px"><div class="card-header"><h2>Configurations créées dans cet aperçu</h2></div>${state.clubs.map(club=>`<div class="list-row"><span class="swatch" style="background:${/^#[0-9a-f]{6}$/i.test(club.color)?club.color:'#2855a7'}"></span><div class="grow"><strong>${E(club.name)}</strong><small>${E(club.city)} · ${E(club.teams)}</small></div>${pill('Locale uniquement')}</div>`).join('')}</section>`:''}`;}
function settingsPage(){return `${heading('Vos repères · Vos données','Un compte, des informations claires.','Dans cet aperçu, votre profil et vos essais restent sur cet appareil.')}<div class="two-col"><form id="profile-form" class="card"><div class="profile-header">${state.profile.photo?`<img src="${E(state.profile.photo)}" alt="Photo choisie dans l’aperçu">`:'<span class="avatar">EM</span>'}<div><h2>Mon profil</h2><p class="subtitle">Profil de démonstration</p></div></div><label class="field">Prénom et nom<input name="name" value="${E(state.profile.name)}" required maxlength="80"></label><label class="field">Adresse e-mail de démonstration<input name="email" type="email" value="${E(state.profile.email)}" required maxlength="150"><small>Aucun e-mail ne sera envoyé.</small></label><label class="photo-label">Ajouter une photo de profil pour tester<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp"><span>JPEG, PNG ou WebP · 5 Mo maximum, redimensionnée avant sauvegarde.</span></label><button class="button primary" type="submit">Enregistrer mon profil ici</button></form><div class="stack"><section class="card"><div class="card-header"><h2>Où est mon travail ?</h2>${pill(storageFailed?'Action nécessaire':'Sur cet appareil',storageFailed?'red':'green')}</div><p class="report-note">Dernière sauvegarde locale : <strong>${timeLabel()}</strong>. Les textes, présences et préférences de cette démonstration sont séparés du site réel.</p><div class="actions">${btn('Comprendre les statuts','sync','ghost')}${btn('Télécharger mes essais (.json)','export','ghost')}</div></section><section class="card"><div class="card-header"><h2>Photos de la causerie</h2>${pill(state.photos.length+' / 6')}</div><label class="photo-label">Tester l’ajout d’une photo<input id="talk-photo" type="file" accept="image/jpeg,image/png,image/webp"></label>${state.photos.length?`<div class="photo-grid">${state.photos.map(photo=>`<img src="${E(photo)}" alt="Photo ajoutée dans la démonstration">`).join('')}</div>`:'<p class="report-note">Ajoutez une photo pour voir comment elle est conservée dans le prototype.</p>'}<div class="notice blue">La synchronisation entre appareils et la sécurité des photos nécessitent une mise en œuvre et des tests sur le serveur. Elles ne sont pas actives dans cet aperçu.</div></section></div></div>`;}
const improvements=[['01','Un accueil qui donne la prochaine action','Reprendre la causerie, voir la semaine et retrouver le prochain bilan, sans chercher parmi les menus.','accueil'],['02','Un même match, partout','Un encadré commun relie agenda, causerie et bilan. Chaque rencontre possède ses propres textes dans la démonstration.','match'],['03','Une causerie plus complète','Contexte du match, messages du vestiaire, jeu avec et sans ballon, transitions et prévisualisation des diapositives.','match'],['04','Le bilan prépare déjà la suite','Les intentions de la causerie restent visibles pendant le bilan. Le point à travailler conduit vers les séances.','bilans'],['05','Les présences pour tout le groupe','Deux dates visibles pour tous les joueurs, actions P / A / E et pointage de tout le groupe. Commandes adaptées au tactile.','effectif'],['06','Des sauvegardes compréhensibles','Statut local réel, simulation hors ligne, explication des futurs statuts de synchronisation et export JSON de vos essais.','reglages'],['07','Un responsable mieux renseigné','Assiduité, périodes, dénominateurs, bilans et détails par catégorie, avec simulation de l’affichage selon le rôle.','responsable'],['08','Un parcours pour les clubs pilotes','Création guidée de l’identité, des équipes et du contact. La configuration est conservée localement, sans invitation envoyée.','club'],['09','Une interface plus cohérente','Même hiérarchie, mêmes boutons et espacements. Identité Stade Mayennais conservée et photos d’accueil en fond.','accueil'],['10','Un aperçu plus léger et accessible','Aucune grosse bibliothèque chargée. Polices locales, liens directs, clavier, focus visible et prise en compte du mouvement réduit.','agenda']];
function improvementsPage(){return `${heading('Le tour des améliorations','Le même club. Un parcours plus fluide.','Un aperçu concret à parcourir, avant toute modification du produit actuel.',link('Commencer la visite →','accueil','dark'))}<div class="notice blue" style="margin-bottom:24px"><strong>Ce qui fonctionne ici :</strong> navigation, formulaires, pointage des présences, ajout de situations, photos redimensionnées, export JSON et sauvegarde locale.<br><strong>Ce qui reste à développer / vérifier :</strong> synchronisation réelle entre appareils, droits d’accès Supabase, sauvegardes serveur, invitations et déploiement multi-club. Aucun de ces points n’est validé par une maquette.</div><div class="feature-grid">${improvements.map(([num,title,desc,route])=>`<article class="card feature-card"><span class="feature-index">${num}</span><h3>${title}</h3><p>${desc}</p><a class="text-link" href="#${route}" style="display:inline-block;margin-top:15px">Explorer cet écran ↗</a></article>`).join('')}</div>`;}
const pages={accueil:home,match:matchPage,seances:sessionsPage,agenda:agendaPage,bilans:reportsPage,effectif:attendancePage,responsable:managerPage,club:clubPage,reglages:settingsPage,ameliorations:improvementsPage};
function render(scroll=false){const route=location.hash.slice(1)||'accueil';currentRoute=pages[route]?route:'accueil';document.querySelector('#navigation').innerHTML=navItems.map(([id,title],i)=>`${i===6?'<div class="nav-divider"></div>':''}<a href="#${id}" ${currentRoute===id?'class="active" aria-current="page"':''}><span class="nav-icon">${icon(id)}</span>${title}</a>`).join('');document.querySelector('#breadcrumb').textContent=navItems.find(([id])=>id===currentRoute)?.[1]||'Les améliorations';document.querySelector('#main').innerHTML=decorate(pages[currentRoute]());document.body.classList.toggle('home-backdrop',currentRoute==='accueil');document.title=`${navItems.find(([id])=>id===currentRoute)?.[1]||'Les améliorations'} · CRUZA — aperçu`;updateHeader();if(scroll){window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});}document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');}
function modal(title,body){const dialog=document.querySelector('#modal');document.querySelector('#modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button data-action="close" aria-label="Fermer">×</button></div>${decorate(body)}`;if(!dialog.open)dialog.showModal();}
function syncModal(){modal('Votre travail, au bon endroit.',`<p class="modal-intro">Le statut de cette démonstration est <strong>local uniquement</strong>. Voici comment le produit pourrait rendre chaque situation compréhensible.</p><div class="sync-state"><span class="sync-icon">✓</span><div><strong>${storageFailed?'Stockage local indisponible':'Conservé sur cet appareil'}</strong><p>${storageFailed?'Exportez vos essais pour ne pas les perdre.':'Dernière sauvegarde : '+timeLabel()+'. Vous pouvez reprendre ici après un rechargement.'}</p></div></div><div class="sync-state"><span class="sync-icon" style="color:#8797ac">↗</span><div><strong>Disponible sur mes autres appareils</strong><p>Non actif dans cet aperçu. Ce statut ne devra apparaître qu’après confirmation réelle du serveur.</p></div></div><div class="sync-state"><span class="sync-icon" style="color:#b58d35">!</span><div><strong>Action nécessaire</strong><p>En cas de conflit ou de quota, conserver le document ouvert et proposer un export, sans relancer en boucle.</p></div></div><div class="sync-settings"><label class="switch-row">Simuler une utilisation hors ligne<input id="offline-switch" type="checkbox" ${state.offline?'checked':''}></label><div class="actions">${btn('Télécharger mes essais','export','primary')}${btn('Fermer','close','ghost')}</div></div>`);}
function exportData(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Fichier préparé. Vérifiez les téléchargements de votre navigateur.');}
function chooseMatch(){modal('Choisir le match à préparer',`<p class="modal-intro">La préparation et le bilan resteront rattachés à cette rencontre. Vos autres essais sont conservés séparément.</p>${Object.values(matches).map(match=>`<div class="list-row"><div class="grow"><strong>${E(match.short)}</strong><small>${match.date} · ${match.number}</small></div>${btn(state.match===match.id?'Match actif':'Choisir','select-match',state.match===match.id?'primary small':'ghost small',`data-match="${match.id}"`)}</div>`).join('')}`);}
function wizard(){const fields=wizardStep===1?`<label class="field">Nom du club<input name="name" required maxlength="80" value="${E(wizardData.name)}" placeholder="Ex. Club pilote"></label><label class="field">Ville<input name="city" required maxlength="80" value="${E(wizardData.city)}" placeholder="Ville du club"></label><label class="field">Couleur principale<input type="color" name="color" value="${wizardData.color}"></label>`:wizardStep===2?`<label class="field">Catégories<input name="teams" required maxlength="120" value="${E(wizardData.teams)}"><small>Séparez les catégories par des virgules.</small></label><label class="field">Contact responsable<input type="email" name="email" required maxlength="150" value="${E(wizardData.email)}" placeholder="responsable@exemple.fr"><small>Information locale. Aucune invitation ne sera envoyée.</small></label>`:`<div class="wizard-preview" style="background:${/^#[0-9a-f]{6}$/i.test(wizardData.color)?wizardData.color:'#2855a7'}"><small>CONFIGURATION DU CLUB PILOTE</small><h3>${E(wizardData.name)}</h3><p>${E(wizardData.city)} · ${E(wizardData.teams)}</p></div><p class="modal-intro">Contact : ${E(wizardData.email)}.<br>La validation conserve cette configuration dans l’aperçu uniquement.</p>`;modal('Un club prêt à démarrer.',`<div class="step-counter">ÉTAPE ${wizardStep} / 3</div><form id="club-wizard">${fields}<div class="actions">${wizardStep>1?btn('Retour','wizard-back','ghost'):''}<button type="submit" class="button primary">${wizardStep===3?'Conserver la configuration':'Continuer →'}</button></div></form>`);}
function slides(){const draft=state.drafts[state.match]||{};modal('Votre causerie, en un coup d’œil.',`<p class="modal-intro">Prévisualisation des contenus enregistrés pour ${E(m().short)}. Cet aperçu ne génère pas de fichier Canva ou PowerPoint.</p>${[['Contexte du match',draft.context],['Notre intention',draft.intention],['Messages clés',draft.messages],['Avec le ballon',draft.withBall],['Sans le ballon',draft.withoutBall],['Transitions',draft.transition]].map(([title,text])=>`<section class="card" style="margin-bottom:12px"><div class="eyebrow">${title}</div><p style="font-size:12px;white-space:pre-line">${text?E(text):'À renseigner et enregistrer dans la préparation.'}</p></section>`).join('')}${state.photos.length?`<div class="photo-grid">${state.photos.map(photo=>`<img src="${E(photo)}" alt="Photo ajoutée">`).join('')}</div>`:''}${btn('Fermer','close','primary')}`);}
function captureDraft(){const form=document.querySelector('#talk-form')||document.querySelector('#animation-form');if(form)state.drafts[state.match]={...(state.drafts[state.match]||{}),...Object.fromEntries(new FormData(form))};const report=document.querySelector('#report-form');if(report)state.reports[state.match]={...(state.reports[state.match]||{}),...Object.fromEntries(new FormData(report))};}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 if(action==='close'){document.querySelector('#modal').close();return;}
 if(action==='sync')return syncModal();
 if(action==='choose-match')return chooseMatch();
 if(action==='select-match'){captureDraft();state.match=el.dataset.match;if(!matches[state.match])state.match='next';persist(true);document.querySelector('#modal').close();if(currentRoute==='agenda')location.hash='match';else render();return;}
 if(action==='tab'){captureDraft();persist(true);currentTab=el.dataset.tab;render();return;}
 if(action==='ready'){captureDraft();state.ready[state.match]=el.checked;persist();return;}
 if(action==='check-prep'){captureDraft();state.drafts[state.match]={...(state.drafts[state.match]||{}),checked:el.checked};persist(true);return;}
 if(action==='after-match'){captureDraft();state.played[state.match]=true;persist(true);location.hash='bilans';render();toast('Scénario après-match activé. Le même match est conservé.');return;}
 if(action==='slides'){captureDraft();persist(true);return slides();}
 if(action==='filter'){exerciseFilter=el.dataset.filter;render();return;}
 if(action==='add-exercise'){const index=Number(el.dataset.index);state.session=state.session.includes(index)?state.session.filter(i=>i!==index):[...state.session,index];persist(true);render();toast(state.session.includes(index)?'Situation ajoutée à votre séance de démonstration.':'Situation retirée de votre séance.');return;}
 if(action==='exercise-detail'){const ex=exercises[Number(el.dataset.index)];return modal(ex.title,`${exercisePreview(Number(el.dataset.index))}<p class="report-note">${ex.detail} · ${ex.theme}</p><div class="eyebrow">OBJECTIF</div><p class="report-note">Créer des solutions autour du porteur et reconnaître le joueur libre.</p><div class="eyebrow">ORGANISATION</div><p class="report-note">Terrain de 25 × 30 mètres. Alterner les rôles toutes les 3 minutes. Adapter les distances au niveau du groupe.</p><div class="notice blue">Fiche illustrative, sans modification de la bibliothèque réelle.</div>`);}
 if(action==='session')return modal('Ma séance · mercredi 18 novembre',`<p class="modal-intro">Votre sélection est conservée dans cet aperçu.</p>${state.session.length?state.session.map((index,i)=>`<div class="list-row"><span class="list-number">${i+1}</span><div><strong>${exercises[index].title}</strong><small>${exercises[index].detail}</small></div></div>`).join(''):'<div class="notice blue">Ajoutez des situations depuis la bibliothèque pour construire votre séance.</div>'}<div class="actions" style="margin-top:20px">${btn('Exporter la séance','export-session','primary')}${btn('Fermer','close','ghost')}</div>`);
 if(action==='export-session')return exportData({preview:true,date:'2026-11-18',team:state.team,exercises:state.session.map(i=>exercises[i])},'cruza-apercu-seance.json');
 if(action==='presence'){const day=el.dataset.day,index=el.dataset.player;state.attendance[day]||={};if(state.attendance[day][index]===el.dataset.presence)delete state.attendance[day][index];else state.attendance[day][index]=el.dataset.presence;persist(true);attendanceDay=day;render();return;}
 if(action==='attendance-day'){attendanceDay=el.dataset.day;render();return;}
 if(action==='all-present'){state.attendance[attendanceDay]=Object.fromEntries(players.map((_,i)=>[i,'present']));persist();render();return;}
 if(action==='new-club'){wizardStep=1;return wizard();}
 if(action==='wizard-back'){wizardStep=Math.max(1,wizardStep-1);return wizard();}
 if(action==='export'){captureDraft();persist(true);return exportData({preview:true,exportedAt:new Date().toISOString(),...state},'cruza-apercu-mes-essais.json');}
 if(action==='export-manager')return exportData({preview:true,period:'Novembre 2026',categories:[{name:'U15',attendance:76,reports:'3/4'},{name:'U17',attendance:88,reports:'4/4'},{name:'Seniors',attendance:94,reports:'1/2'}]},'cruza-apercu-synthese-fictive.json');
 if(action==='category'){const cat=el.dataset.category;return modal(`${E(cat)} · regarder au-delà du score`, `<p class="modal-intro">Statistiques fictives · novembre 2026 · 6 séances observées.</p><div class="list-row"><div class="grow"><strong>Assiduité à l’entraînement</strong><small>Présences réellement pointées / joueurs attendus.</small></div>${pill(cat==='U15'?'38 / 50 · 76 %':cat==='U17'?'44 / 50 · 88 %':'47 / 50 · 94 %','green')}</div><div class="list-row"><div><strong>Travail de la catégorie</strong><small>Conservation, réaction à la perte, progression vers le but.</small></div></div><div class="list-row"><div><strong>Continuité pédagogique</strong><small>3 séances reliées à un point du bilan précédent.</small></div></div><div class="notice blue" style="margin-top:20px">Des indicateurs pour accompagner. Les résultats seuls ne permettent pas d’évaluer le travail d’un éducateur.</div>`);}
 if(action==='add-event')return modal('Ajouter depuis le bon contexte.',`<p class="modal-intro">Dans cette version de démonstration, les rendez-vous sont prédéfinis pour tester le parcours.</p><div class="actions">${link('Préparer une séance','seances','primary')}${btn('Choisir un match','choose-match','ghost')}</div><p class="card-note">La création complète d’événements reste dans l’agenda du site réel.</p>`);
});
document.addEventListener('submit',event=>{if(!['talk-form','animation-form','report-form','profile-form','club-wizard'].includes(event.target.id))return;event.preventDefault();const values=Object.fromEntries(new FormData(event.target));
 if(event.target.id==='talk-form'||event.target.id==='animation-form'){state.drafts[state.match]={...(state.drafts[state.match]||{}),...values};persist();render();}
 if(event.target.id==='report-form'){state.reports[state.match]={...values,saved:true};persist();render();}
 if(event.target.id==='profile-form'){state.profile={...state.profile,...values};persist();render();}
 if(event.target.id==='club-wizard'){wizardData={...wizardData,...values};if(wizardStep<3){wizardStep++;wizard();}else{state.clubs.push({...wizardData,createdAt:new Date().toISOString()});persist();document.querySelector('#modal').close();render();}}
});
document.addEventListener('input',event=>{if(event.target.id==='exercise-search'){const start=event.target.selectionStart;exerciseSearch=event.target.value;render();const input=document.querySelector('#exercise-search');input.focus();input.setSelectionRange(start,start);}else if(event.target.closest('#talk-form,#animation-form,#report-form')){captureDraft();persist(true);}});
document.addEventListener('change',async event=>{const el=event.target;
 if(el.id==='team-select'){captureDraft();const old=state.team;const next=el.value;state.team=old;persist(true);const base=defaults();try{const raw=localStorage.getItem(KEY+'-team-'+next);const other=raw?JSON.parse(raw):{};localStorage.setItem(KEY+'-team-'+old,JSON.stringify({drafts:state.drafts,reports:state.reports,attendance:state.attendance,session:state.session,ready:state.ready,played:state.played,match:state.match}));for(const key of ['drafts','reports','attendance','session','ready','played','match'])state[key]=other[key]??base[key];}catch{storageFailed=true;}state.team=next;persist(true);render();toast('Équipe changée. Les préparations restent séparées.');}
 if(el.id==='role-select'){state.role=el.value;persist(true);render();}
 if(el.id==='offline-switch'){state.offline=el.checked;persist(true);toast(state.offline?'Simulation hors ligne : vos essais restent sur cet appareil.':'Simulation hors ligne désactivée. Aucune connexion serveur dans cet aperçu.');}
 if(el.id==='profile-photo'||el.id==='talk-photo'){const file=el.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Choisissez une image JPEG, PNG ou WebP de moins de 5 Mo.');el.value='';return;}if(el.id==='talk-photo'&&state.photos.length>=6){toast('Six photos maximum dans cette démonstration.');return;}try{const url=URL.createObjectURL(file),image=new Image();try{image.src=url;await image.decode();const canvas=document.createElement('canvas'),scale=Math.min(1,800/Math.max(image.width,image.height));canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const photo=canvas.toDataURL('image/jpeg',.75);if(el.id==='profile-photo')state.profile.photo=photo;else state.photos.push(photo);}finally{URL.revokeObjectURL(url);}persist();render();}catch{toast('Cette image ne peut pas être lue. Essayez une autre photo.');}}
});
document.querySelector('#save-indicator').addEventListener('click',syncModal);
document.querySelector('#profile-button').addEventListener('click',()=>location.hash='reglages');
document.querySelector('.mobile-menu').addEventListener('click',()=>{const open=document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');}});
document.querySelector('#modal').addEventListener('click',event=>{if(event.target===event.currentTarget){const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.currentTarget.close();}});
document.querySelector('#modal').addEventListener('click',event=>{if(event.target.closest('a[href^="#"]'))event.currentTarget.close();});
window.addEventListener('hashchange',()=>render(true));
render();
